#nullable enable

using System.Linq;
using IIIF.ImageApi.V2;
using IIIF.Presentation.V3;
using IIIF.Presentation.V3.Content;
using IIIF.Presentation.V3.Traversal;
using IIIF.Serialisation;

namespace IIIF.Tests.Serialisation;

/// <summary>
/// Tests for Manifest containing an ImageService2 with no "@type"/"type" and "profile" in array format, as
/// generated by some image servers
/// </summary>
public class ImageService2ProfileArrayManifestTests
{
    private const string ManifestId = "https://example.org/manifest";
    private const string ImageServiceId = "https://example.org/iiif/image.jp2";

    private const string Json = $$"""
        {
          "@context": "http://iiif.io/api/presentation/3/context.json",
          "id": "{{ManifestId}}",
          "type": "Manifest",
          "label": { "en": [ "ImageService2 profile array" ] },
          "items": [
            {
              "id": "https://example.org/canvas/1",
              "type": "Canvas",
              "height": 2000,
              "width": 1500,
              "items": [
                {
                  "id": "https://example.org/canvas/1/page",
                  "type": "AnnotationPage",
                  "items": [
                    {
                      "id": "https://example.org/canvas/1/page/painting",
                      "type": "Annotation",
                      "motivation": "painting",
                      "target": "https://example.org/canvas/1",
                      "body": {
                        "id": "https://example.org/iiif/image.jp2/full/max/0/default.jpg",
                        "type": "Image",
                        "format": "image/jpeg",
                        "height": 2000,
                        "width": 1500,
                        "service": [
                          {
                            "@context": "http://iiif.io/api/image/2/context.json",
                            "@id": "{{ImageServiceId}}",
                            "id": "{{ImageServiceId}}",
                            "protocol": "http://iiif.io/api/image",
                            "width": 1500,
                            "height": 2000,
                            "profile": [
                              "http://iiif.io/api/image/2/level1.json",
                              {
                                "formats": [ "jpg", "png", "tif" ],
                                "qualities": [ "native", "gray", "bitonal" ],
                                "supports": [ "regionByPct", "sizeByConfinedWh", "mirroring" ],
                                "maxWidth": 1200,
                                "maxHeight": 1200
                              }
                            ]
                          }
                        ]
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
        """;

    private readonly Manifest manifest = Json.FromJson<Manifest>()!;

    [Fact]
    public void Deserialises_WithoutException()
    {
        manifest.Should().NotBeNull();
        manifest.Id.Should().Be(ManifestId);
    }

    [Fact]
    public void ImageService_WithoutType_IdentifiedAsImageService2()
    {
        var service = GetImageBody().Service.Should().ContainSingle().Subject;

        service.Should().BeOfType<ImageService2>("type is identified from image/2 profile");
    }

    [Fact]
    public void ImageService2_ProfileArray_PopulatesProfileAndDescription()
    {
        var imageService = GetImageService2();

        imageService.Id.Should().Be(ImageServiceId);
        imageService.Profile.Should().Be(ImageService2.Level1Profile);
        imageService.Protocol.Should().Be(ImageService2.Image2Protocol);
        imageService.Width.Should().Be(1500);
        imageService.Height.Should().Be(2000);

        var description = imageService.ProfileDescription;
        description.Should().NotBeNull();
        description.Formats.Should().BeEquivalentTo("jpg", "png", "tif");
        description.Qualities.Should().BeEquivalentTo("native", "gray", "bitonal");
        description.Supports.Should().BeEquivalentTo("regionByPct", "sizeByConfinedWh", "mirroring");
        description.MaxWidth.Should().Be(1200);
        description.MaxHeight.Should().Be(1200);
    }

    [Fact]
    public void RoundTrip_PreservesProfileArray()
    {
        var reserialised = manifest.AsJson().FromJson<Manifest>()!;

        var imageService = reserialised.AllPaintingAnnoBodies<Image>().Single().Service!.Single()
            .Should().BeOfType<ImageService2>().Subject;
        imageService.Profile.Should().Be(ImageService2.Level1Profile);
        imageService.ProfileDescription.MaxWidth.Should().Be(1200);
    }

    private Image GetImageBody() => manifest.AllPaintingAnnoBodies<Image>().Should().ContainSingle().Subject;

    private ImageService2 GetImageService2() => (ImageService2)GetImageBody().Service!.Single();
}
